{
 "didatica": [
  {
   "campo": "resolucao.antes.texto",
  "depois": "A questão pede que você julgue quatro afirmativas sobre três autores clássicos. Em cada uma, confira se o que se atribui ao autor é mesmo dele. Durkheim defende uma moral própria das profissões e a solidariedade como base da sociedade. Marx liga as ideias às condições materiais e às classes. Weber descreve a modernidade como racionalização e desencantamento do mundo.",
   "motivo": "Mantido; já está claro e curto."
  },
  {
   "campo": "resolucao.antes.simbolos",
   "depois": [
    ["Anomia", "Em Durkheim, ausência ou enfraquecimento das regras que orientam a conduta, como na anarquia econômica."],
    ["Ideologia", "Em Marx, conjunto de ideias que expressa o interesse de uma classe e esconde a realidade social."],
    ["Falsa consciência", "Ideia de que as pessoas enxergam a sociedade de modo distorcido, sem perceber os interesses de classe por trás das ideias."],
    ["Desencantamento do mundo", "Em Weber, perda da explicação mágica ou religiosa da vida, trocada pelo cálculo e pela razão."],
    ["Racionalização", "Em Weber, organização da vida por regras, cálculo e eficiência, e não por tradição ou crença."],
    ["Socialização", "Processo em que a pessoa aprende normas, valores e modos de agir da sociedade."],
    ["Fake news", "Notícias falsas espalhadas como se fossem verdadeiras."]
   ],
   "motivo": "Incluir termos técnicos que aparecem na resolução (falsa consciência, racionalização, fake news) e simplificar definições."
  },
  {
   "campo": "resolucao.pista",
   "depois": "Em cada afirmativa, pergunte: este autor realmente disse isso? Confira palavra por palavra, pois alguns conceitos podem estar de ponta-cabeça.",
   "motivo": "A pista antiga citava as palavras 'encantamento' e 'afeto', o que entregava qual afirmativa estava errada."
  },
  {
   "campo": "resolucao.passos[0].porque",
   "depois": "Durkheim propõe uma moral própria para as profissões (prefácio da 2ª edição de Da divisão do trabalho social). Ele diz que a sociedade só tem razão de ser se trouxer paz e harmonia, apesar do egoísmo e da anarquia econômica. A afirmativa é verdadeira.",
   "motivo": "Frases mais curtas e diretas."
  },
  {
   "campo": "resolucao.passos[2].porque",
   "depois": "Em A ideologia alemã, Marx liga a produção das ideias à atividade material. As ideias expressam a posição de classe, e a ideologia distorce a realidade. 'Falsa consciência' é expressão de Engels (1893), usada para resumir essa ideia marxista. A afirmativa é verdadeira.",
   "motivo": "Simplificação e frases mais curtas."
  },
  {
   "campo": "resolucao.passos[3].porque",
   "depois": "Weber fala em desencantamento do mundo (não 'encantamento'), em separação das esferas de valor (não 'redução') e em racionalização (não 'ampliação do afeto'). Os três pontos estão invertidos. A afirmativa é falsa.",
   "motivo": "Clareza."
  },
  {
   "campo": "resolucao.erradas.A",
   "depois": "Faltou ver que a 2 é falsa: notícias e moral nascem da socialização e das regras sociais. Faltou também reconhecer que a 1 e a 3 são verdadeiras e ficaram de fora.",
   "motivo": "Dizer o que faltou no raciocínio de quem marcou A."
  },
  {
   "campo": "resolucao.erradas.C",
   "depois": "Faltou notar que a 2 e a 4 são justamente as falsas. Quem marcou C tomou o vocabulário weberiano da 4 como certo e não viu que a 1 e a 3, corretas, ficaram de fora.",
   "motivo": "Foco no erro de raciocínio do aluno."
  },
  {
   "campo": "resolucao.erradas.D",
   "depois": "Faltou ler a 4 palavra por palavra. Para Weber, a modernidade traz desencantamento e racionalização, não 'encantamento' nem mais afeto. A 1 e a 3 estão certas, mas incluir a 4 torna a alternativa errada.",
   "motivo": "Mostrar onde o aluno deixou de conferir."
  },
  {
   "campo": "resolucao.erradas.E",
   "depois": "Faltou testar cada afirmativa em separado. A 2 nega a socialização e a 4 inverte os traços da modernidade em Weber. Aceitar tudo sem conferir leva a esta letra.",
   "motivo": "Explicar o raciocínio que faltou."
  },
  {
   "campo": "resolucao.resposta",
   "depois": "Alternativa B — somente as afirmativas 1 e 3 são verdadeiras. A 2 nega a socialização e a 4 inverte Weber.",
   "motivo": "Padronizar o formato e encurtar."
  }
 ],
 "didatica_alertas": [],
 "didatica_ok": true
}
